  if group=='M-I':
   index=int(q['id'].split('-')[2]);module='get-started-with-generative-ai-and-agents/7-knowledge-check' if index<=12 else 'get-started-text-analysis-azure/6-knowledge-check' if index<=15 else 'get-started-speech-azure/6-knowledge-check' if index<=18 else 'get-started-vision-azure/6-knowledge-check' if index<=21 else 'get-started-information-extraction/5-knowledge-check'
  if module:q['moduleAssessment']='https://learn.microsoft.com/en-us/training/modules/'+module
