   correct=[('질문과 관련된 최신 문서를 검색해 요청 맥락에 제공한다','모델에 없는 최신 업무 근거를 전달한다.'),('답변과 출처를 대조하고 근거가 부족할 때의 처리를 둔다','검색을 사용해도 부정확한 답변이 가능하므로 검증이 필요하다.')] if prefix=='M-C-17' else [('업무 필드의 이름과 적절한 자료형을 정의한다','원하는 결과 구조와 자료형을 명시한다.'),('각 필드가 뜻하는 값과 추출 요구를 설명한다','업무상 의미와 구분 조건을 모델에 안내한다.')]
   wrong=[(o['text'],o['reason']) for o in q['options'] if o['id']!='a']
